mapper.select:
SELECT money.biz_date AS biz_date, SUM(money.collected) AS collected, SUM(money.refunded) AS refunded, SUM(money.collected - money.refunded) AS revenue, SUM(money.invoices) AS invoice_count FROM ( SELECT CAST(paid_at AS DATE) AS biz_date, amount AS collected, CAST(0 AS DECIMAL(13,2)) AS refunded, 1 AS invoices FROM payments WHERE status = 'COMPLETED' AND paid_at >= #{from} AND paid_at < #{until} UNION ALL SELECT CAST(refunded_at AS DATE) AS biz_date, CAST(0 AS DECIMAL(13,2)) AS collected, amount AS refunded, 0 AS invoices FROM refunds
AND refunded_at >= #{from} AND refunded_at < #{until}
) money GROUP BY money.biz_date ORDER BY money.biz_date

SELECT s.employee_id AS employee_id, SUM(r.amount) AS total FROM refunds r JOIN counter_shifts s ON s.id = r.counter_shift_id
AND r.refunded_at >= #{from} AND r.refunded_at < #{until}
GROUP BY s.employee_id
